INSERT INTO policy_version VALUES ('9d6707e3-8e91-55d9-9d56-bd2e8daf9f26','1f4a294e-308f-528e-a614-7ec80aaac910','CUTLEDGER_CAMPAIGN_V1',1,1,'1058f39d6c9d17eec8d268c918481da6d353aa81a3c3fc11097a70d538c672b5','{"V1-DIST-ORG":"ORGANIC30 permits organic distribution only.","V1-DIST-PAID":"PAID90 and GLOBAL365 permit organic distribution and paid advertising.","V1-EXCLUSIONS":"Television, cinema, resale, exclusivity, sublicensing, AI training, and unmodeled uses are not offered.","V1-PLATFORMS":"All tiers permit Instagram, YouTube, and the campaign website.","V1-TERR-US":"ORGANIC30 permits use in the United States (US).","V1-TERR-USGB":"PAID90 permits use in the United States (US) and United Kingdom (GB).","V1-TERR-WORLD":"GLOBAL365 permits use worldwide.","V1-UPGRADE-CREDIT":"The highest compatible active grant value is credited toward the complete higher tier for the same asset, campaign and policy version. Upgrades never restart the anchor window.","V1-WINDOW-30":"ORGANIC30 covers [campaign anchor, campaign anchor + 30 calendar days).","V1-WINDOW-365":"GLOBAL365 covers [campaign anchor, campaign anchor + 365 calendar days).","V1-WINDOW-90":"PAID90 covers [campaign anchor, campaign anchor + 90 calendar days)."}'::jsonb,'2026-11-10T00:00:00Z');
